#include "alosmm/engine.hpp"
int main(int argc,char**argv){try{std::filesystem::path cfg="config/alo_smm.json";bool self=false,print=false;for(int i=1;i<argc;++i){std::string a=argv[i];if(a=="--config"&&i+1<argc)cfg=argv[++i];else if(a=="--self-test")self=true;else if(a=="--print-config")print=true;else if(a=="--help"){std::cout<<"alo-smm [--config path] [--self-test] [--print-config]\n";return 0;}}auto c=alosmm::load_config(cfg);if(print){std::cout<<alosmm::config_summary(c)<<"\n";return 0;}auto e=std::make_unique<alosmm::Engine>(std::move(c));return self?e->self_test():e->run();}catch(const std::exception&e){std::cerr<<"FATAL: "<<e.what()<<"\n";return 1;}}
